SOURCE_PARAMETERS={'coefficient':{'a':4,'b':2,'c':3,'d':-11,'e':12},'augmented':{'k':4,'l':11,'m':3,'r':-1}}
EASY_SOURCES={
    'q-129137':([1,3,9,-4,2,1],['p','q']),
